const items = $('Batch Input').all();
const esc = s => String(s).replace(/'/g, "''");
const erps = items
  .map(i => String(i.json.properties?.erp_account_number || '').trim())
  .filter(Boolean);
if (erps.length === 0) {
  // sentinel that matches nothing, avoids fetching the entire table
  return [{ json: { customerFilter: "No eq 'ZZ_NO_MATCH'", shipToFilter: "HFSCustomerNo eq 'ZZ_NO_MATCH'" } }];
}
return [{ json: {
  customerFilter: erps.map(e => `No eq '${esc(e)}'`).join(' or '),
  shipToFilter:   erps.map(e => `HFSCustomerNo eq '${esc(e)}'`).join(' or ')
} }];

const shipRows = $input.first().json.value || [];
const custRows = $('Get Customer Data').first().json.value || [];
const batch = $('Batch Input').all().map(i => i.json);

const routeMap = {
  'RT 1':  'Route 1',  'RT 2':  'Route 2',  'RT 3':  'Route 3',
  'RT 4':  'Route 4',  'RT 5':  'Route 5',  'RT 6':  'Route 6',
  'RT 7':  'Route 7',  'RT 8':  'Route 8',  'RT 9':  'Route 9',
  'RT 10': 'Route 10', 'RT 11': 'Route 11', 'RT 12': 'Route 12',
  'RT 13': 'Route 13', 'RT 15': '15 - Greenville',
  'RT 16': 'Route 16 - Boxed', 'RT 20': 'Route 20 - Supervisor',
  'RT 21': 'Route 21 - Distribution'
};
const paymentMethodMap = {
  'ACH':   'ACH Upon Due Date',   'CCA': 'Credit Card Auto',
  'CCW':   'Credit Card Weekly',  'Check': 'Check',
  'COD':   'Cash on Delivery',    'CCM': 'Credit Card Monthly',
  'CCP':   'Credit Card Payment Plan'
};
const salespersonMap = {
  'CUDICK':  '90537115',
  'DHALL':   '58718266',
  'LLONG':   '53148531',
  'GCOPLIN': '89639254',
  'HWEST':   '53148526'
};

function calendarToDays(code) {
  if (!code) return null;
  const days = [];
  let i = 0;
  while (i < code.length) {
    if (code.slice(i, i+2) === 'TH') { days.push('Thursday');  i += 2; }
    else if (code[i] === 'M')        { days.push('Monday');    i++; }
    else if (code[i] === 'T')        { days.push('Tuesday');   i++; }
    else if (code[i] === 'W')        { days.push('Wednesday'); i++; }
    else if (code[i] === 'F')        { days.push('Friday');    i++; }
    else if (code[i] === 'S')        { days.push('Saturday');  i++; }
    else i++;
  }
  const order = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  return order.filter(d => days.includes(d)).join(';') || null;
}

const odataMap = {};
for (const r of custRows) odataMap[String(r.No)] = r;
const shipMap = {};
for (const r of shipRows) {
  const cn = String(r.HFSCustomerNo || '').trim();
  if (cn && !shipMap[cn]) shipMap[cn] = r;
}

const toUpdate = [];
for (const hsCompany of batch) {
  const erpNum = String(hsCompany.properties?.erp_account_number || '').trim();
  if (!erpNum) continue;

  const odata = odataMap[erpNum] || {};
  const hasOdata = Object.keys(odata).length > 0;
  const shipRow = shipMap[erpNum] || {};
  const raw = {};

  if (odata.Balance_LCY     != null) raw.balance     = odata.Balance_LCY;
  if (odata.Balance_Due_LCY != null) raw.balance_due = odata.Balance_Due_LCY;
  const rawRoute = odata.Shipping_Agent_Code ? String(odata.Shipping_Agent_Code).trim() : null;
  if (rawRoute) { const r = routeMap[rawRoute]; if (r) raw.route = r; }
  const days = calendarToDays(odata.Base_Calendar_Code);
  if (days) raw.days_of_delivery = days;

  if (shipRow.Address)   raw.address  = shipRow.Address;
  if (shipRow.Address_2) raw.address2 = shipRow.Address_2;
  if (shipRow.City)      raw.city     = shipRow.City;
  if (shipRow.Post_Code) raw.zip      = shipRow.Post_Code;

  if (hasOdata) {
    const bcBlocked = odata.Blocked && String(odata.Blocked).trim() && String(odata.Blocked).trim() !== '_x0020_';
    if (odata.Name)      raw.name = odata.Name;
    if (odata.Address)   raw.billing_street_address   = odata.Address;
    if (odata.Address_2) raw.billing_street_address_2 = odata.Address_2;
    if (odata.City)      raw.billing_city             = odata.City;
    if (odata.County)    raw.billing_state            = odata.County;
    const zip = odata.Post_Code != null ? String(odata.Post_Code).trim() : '';
    if (zip) raw.billing_zip_code = zip;
    raw.payment_terms_code = odata.Payment_Terms_Code || null;
    const pmCode = odata.Payment_Method_Code ? String(odata.Payment_Method_Code).trim() : null;
    raw.payment_method_code = (pmCode && paymentMethodMap[pmCode]) ? paymentMethodMap[pmCode] : null;
    if (odata.Credit_Limit_LCY != null) raw.credit_limit = odata.Credit_Limit_LCY;
    raw.blocked = bcBlocked ? 'Blocked' : '';
    const spCode = odata.Salesperson_Code ? String(odata.Salesperson_Code).trim() : null;
    if (spCode && salespersonMap[spCode]) raw.hubspot_owner_id = salespersonMap[spCode];
  }

  const props = {};
  for (const [k, v] of Object.entries(raw)) {
    if (v !== null && v !== undefined && v !== '') props[k] = v;
  }
  if (hasOdata && 'blocked' in raw)             props.blocked             = raw.blocked;
  if (hasOdata && 'payment_terms_code' in raw)  props.payment_terms_code  = raw.payment_terms_code;
  if (hasOdata && 'payment_method_code' in raw) props.payment_method_code = raw.payment_method_code;

  if (Object.keys(props).length > 0) {
    toUpdate.push({ id: hsCompany.id, properties: props });
  }
}

return [{ json: { toUpdate, updateCount: toUpdate.length } }];
